import{_ as e,o,c as n,a2 as r}from"./chunks/framework.DGk0zlJw.js";const p=JSON.parse('{"title":"B-803 MVP end-to-end walkthrough (mission brief §Success criteria)","description":"","frontmatter":{},"headers":[],"relativePath":"acceptance-B803-e2e-walkthrough.md","filePath":"acceptance-B803-e2e-walkthrough.md"}'),a={name:"acceptance-B803-e2e-walkthrough.md"};function i(d,t,s,c,l,h){return o(),n("div",null,[...t[0]||(t[0]=[r('<h1 id="b-803-mvp-end-to-end-walkthrough-mission-brief-§success-criteria" tabindex="-1">B-803 MVP end-to-end walkthrough (mission brief §Success criteria) <a class="header-anchor" href="#b-803-mvp-end-to-end-walkthrough-mission-brief-§success-criteria" aria-label="Permalink to &quot;B-803 MVP end-to-end walkthrough (mission brief §Success criteria)&quot;">​</a></h1><blockquote><p>Dependency: run this on <strong>one Windows machine</strong> only after B-801..802 and B-805 are code-complete (CI green). Success criteria (mission brief §MVP): auto-start on boot → see the state in a corner of the desktop at all times → a one-click Run/Retry succeeds, all without <strong>opening a browser or signing in to GitHub</strong>. The invariant items in detail are in <a href="./acceptance-B705-L0-behavior.html">acceptance-B705-L0-behavior.en.md</a> (its 5 real-machine checklist items are ticked off inside B-803). Output: recorded screenshots/archive plus either a fix or an issue for anything found; B-804 additionally needs a <strong>clean Win11 VM</strong> on top of this.</p></blockquote><h2 id="_0-preparation-5-minutes" tabindex="-1">0. Preparation (5 minutes) <a class="header-anchor" href="#_0-preparation-5-minutes" aria-label="Permalink to &quot;0. Preparation (5 minutes)&quot;">​</a></h2><ul><li>[ ] Download <code>beacon-nightly-windows-x86_64-setup.exe</code> (or the portable zip) and verify SHA256SUMS</li><li>[ ] Start screen recording (continuous for the whole run; take separate screenshots of problem points)</li><li>[ ] A machine with GitHub repository access plus one PAT (used for connection entry and Retry)</li><li>[ ] A controllable workflow ready (can be failed on demand and re-run, for example a test workflow in the repository)</li></ul><h2 id="_1-script-main-chain-each-link-of-the-mission-brief-success-criteria" tabindex="-1">1. Script main chain (each link of the mission brief success criteria) <a class="header-anchor" href="#_1-script-main-chain-each-link-of-the-mission-brief-success-criteria" aria-label="Permalink to &quot;1. Script main chain (each link of the mission brief success criteria)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>Step</th><th>Action</th><th>Pass criteria</th><th>Result</th></tr></thead><tbody><tr><td>1</td><td>Install / extract</td><td>Run setup.exe (or extract the zip)</td><td>No errors; Beacon appears in the Start menu (the zip route shows a <code>Beacon.App.exe</code> icon directly)</td><td>☐</td></tr><tr><td>2</td><td>First-launch feedback</td><td>Start Beacon</td><td>Startup notification bubble + tray icon + status capsule in the bottom-right corner; <strong>no main window, and it does not enter the taskbar/Alt-Tab</strong></td><td>☐</td></tr><tr><td>3</td><td>Auto-start on boot</td><td>Check <code>HKCU\\Software\\Microsoft\\Windows\\CurrentVersion\\Run</code></td><td>A Beacon entry pointing at the install path (can be turned off in settings)</td><td>☐</td></tr><tr><td>4</td><td>Enter a connection</td><td>Tray menu → Settings → Connections → type github → fill in Id + Token</td><td>&quot;✓ 已保存&quot;; the connection test returns Healthy</td><td>☐</td></tr><tr><td>5</td><td><strong>Token red line</strong></td><td>Open <code>%AppData%\\Beacon\\connections.json</code> and search the whole file for the PAT itself</td><td><strong>The plaintext token is not found</strong>, only <code>credentialRef</code></td><td>☐</td></tr><tr><td>6</td><td>Add widgets</td><td>Settings → Widgets: <code>github.actions.runs</code> + <code>github.pull_requests</code> (pick a connection, fill the required fields)</td><td>Two entries appear in the list; the L2 panel shows the corresponding rows and counts</td><td>☐</td></tr><tr><td>7</td><td>Pin to the desktop</td><td>Turn on the &quot;钉&quot; switch on the widget row</td><td>A tile appears on L0 (status light + label)</td><td>☐</td></tr><tr><td>8</td><td>Cause a failure</td><td>Fail the controllable workflow once</td><td>The capsule turns red / the count changes + the tray icon is recolored + <strong>a Toast pops up</strong> (with sound per the rule)</td><td>☐</td></tr><tr><td>9</td><td>Drill into the detail</td><td>Click the Toast (or the L2 row) to enter L3</td><td>The detail window shows status/repository/phase/error summary; L0 is not interrupted</td><td>☐</td></tr><tr><td>10</td><td><strong>One-click Retry</strong></td><td>Click [Retry] in L3 (no browser opened at any point)</td><td>The workflow re-runs successfully → Success Toast + the light turns green</td><td>☐</td></tr><tr><td>11</td><td>Settings immediacy</td><td>Change a severity color / motion tier / opacity / capsule toggle</td><td>Takes effect immediately (a theme change taking effect on restart is expected); still in force after a restart</td><td>☐</td></tr><tr><td>12</td><td>Import / export</td><td>Settings → export the configuration; then import it after breaking things</td><td>Behaviour is restored; the exported file contains no token; it prompts to re-enter the secret</td><td>☐</td></tr><tr><td>13</td><td>Offline degradation</td><td>Disconnect the network</td><td>The tile shows a gray hollow light + Last update; no exception dialog; resets automatically on recovery</td><td>☐</td></tr></tbody></table><h2 id="_2-four-interaction-levels-checklist-rfc-§6" tabindex="-1">2. Four interaction levels checklist (RFC §6) <a class="header-anchor" href="#_2-four-interaction-levels-checklist-rfc-§6" aria-label="Permalink to &quot;2. Four interaction levels checklist (RFC §6)&quot;">​</a></h2><ul><li>[ ] An L0 tile single click → L2 opens and takes focus; ESC closes it; it closes automatically on focus loss</li><li>[ ] An L2 row single click → L3 detail; closing L3 returns to the always-resident L0</li><li>[ ] Hovering, dragging, and collapsing/expanding L0 never activates the window and never interrupts the current input focus</li><li>[ ] Every tray menu entry works (panel / settings / notifications / refresh / exit); the hotkey <code>Ctrl+Alt+B</code> summons the panel</li><li>[ ] All 5 items of the B-705 invariant real-machine checklist are ticked (see that document)</li></ul><h2 id="_3-glm-quota-end-to-end-blocking-acceptance-feedback-connect-the-source-→-add-a-widget-→-real-numbers-on-the-board" tabindex="-1">3. GLM quota end to end (blocking acceptance feedback: connect the source → add a widget → real numbers on the board) <a class="header-anchor" href="#_3-glm-quota-end-to-end-blocking-acceptance-feedback-connect-the-source-→-add-a-widget-→-real-numbers-on-the-board" aria-label="Permalink to &quot;3. GLM quota end to end (blocking acceptance feedback: connect the source → add a widget → real numbers on the board)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>Step</th><th>Action</th><th>Pass criteria</th><th>Result</th></tr></thead><tbody><tr><td>G1</td><td>Enter the GLM connection</td><td>Settings → Connections → type <code>bigmodel</code> → Id + PAT (or a raw key)</td><td>The connection test returns Healthy; it suggests &quot;在下方组件向导选该连接，或用『一键添加』即可上板&quot;</td><td>☐</td></tr><tr><td>G2</td><td>One-click example</td><td>Settings → bigmodel module → &quot;一键添加 GLM 额度组件（示例）&quot;</td><td><code>bigmodel.usage:GLM</code> appears in the widget list; Pinned=true pins it automatically; the L0 capsule in the bottom-right corner shows a <strong>value card + progress bar</strong></td><td>☐</td></tr><tr><td>G3</td><td>First number on screen</td><td>Wait ≤10 s (the CI/Ci tier)</td><td>The capsule shows &quot;GLM 额度 · 已用 XX% · 剩 YY tokens · MM-DD HH:MM 重置&quot;; the progress bar fills according to the used percentage; right-clicking the L2 row shows a <code>Source: GLM</code> annotation</td><td>☐</td></tr><tr><td>G4</td><td>Field mapping self-check</td><td>Settings → widget <code>bigmodel.usage:GLM</code> → edit → confirm the <code>total_path/used_path/reset_path</code> mapping is correct</td><td>The field paths match the GLM <code>quota/limit</code> response shape (<code>$.data.total</code> / <code>$.data.used</code> / <code>$.data.reset_at</code>)</td><td>☐</td></tr><tr><td>G5</td><td>Forced manual refresh</td><td>Tray menu → Refresh All</td><td>The value and progress bar refresh live; the log <code>%APPDATA%\\Beacon\\logs\\beacon-*.log</code> has one line per hop (one-click add → fetch → field mapping → render)</td><td>☐</td></tr></tbody></table><blockquote><p>⚠️ <strong>Screenshots must be produced on a real Windows machine</strong> (Linux can only run unit tests / builds; WinUI 3 does not run in that environment). After finishing G1–G5, capture one screenshot of the L0 capsule and one of the L2 panel, save them to <code>docs/img/</code>, and attach them to the PR or reply.</p></blockquote><h2 id="_4-archive" tabindex="-1">4. Archive <a class="header-anchor" href="#_4-archive" aria-label="Permalink to &quot;4. Archive&quot;">​</a></h2><ul><li>[ ] Save recordings and screenshots to <code>docs/img/</code> (large recordings may go into a Release asset with a link from the README)</li><li>[ ] For every failed item: fix it on the spot (through the gate, pushed) or file an issue</li><li>[ ] B-804: run the same script once on a <strong>clean Win11 VM</strong> (download → run → this checklist), recording first-install environment behaviour such as VC++ and SmartScreen</li></ul>',13)])])}const g=e(a,[["render",i]]);export{p as __pageData,g as default};
